    @GameTest(environment="buildupmobtweaks:r4e1b",structure=ARENA,maxTicks=30)
    public void freshBirthSampleNoLoadRerollAndNoEquipmentIssued(GameTestHelper h){SkeletonBehaviorTests.floor(h,true);int dodges=0;
        for(int i=0;i<1000;i++){var m=EntityTypes.PIGLIN.create(h.getLevel(),EntitySpawnReason.NATURAL);m.snapTo(h.absolutePos(new BlockPos(8,2,8)),0,0);m.setImmuneToZombification(true);m.getRandom().setSeed(498000L+i);m.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(m.blockPosition()),EntitySpawnReason.NATURAL,null);var hand=m.getMainHandItem();h.getLevel().addFreshEntity(m);if(m.isBaby())h.assertTrue(m.getAttached(PiglinState.DATA).getStringOr("birth","").equals("none"),"Native baby spawn does not roll adult dodge trait");if(m.getAttached(PiglinState.DATA).getStringOr("birth","").equals("dodge"))dodges++;h.assertTrue(m.getMainHandItem()==hand&&m.getOffhandItem().isEmpty()&&m.getInventory().isEmpty(),"Native spawn gear untouched, no reserves");m.discard();}
        h.assertTrue(dodges>=30&&dodges<=110,"70/1000 native finalize/load fixture, not natural spawner evidence");var m=piglin(h,Items.CROSSBOW,false);var d=m.getAttached(PiglinState.DATA);d.putString("birth","none");d.putLong("dodge_ready",998877);var loaded=CombatTestWorld.reload(h,m);h.assertTrue(loaded.getAttached(PiglinState.DATA).getStringOr("birth","").equals("none")&&loaded.getAttached(PiglinState.DATA).getLongOr("dodge_ready",0)==998877,"Saved birth/cooldown never rerolled");BuildupMobTweaks.LOGGER.info("R4E1B_PROOF scenario=birth_sample n=1000 dodge={} natural_spawner=NOT_RUN",dodges);clean(loaded);h.succeed();}
