    @GameTest(environment="buildupmobtweaks:r4e1b_qa",structure=ARENA,maxTicks=680)
    public void independentQaPiglinScenesUseNativeBrainAndCleanup(GameTestHelper h){var origin=h.absolutePos(new BlockPos(14,2,14));var server=h.getLevel().getServer();QaHarness.Session[] s={null};
        h.runAtTickTime(5,()->s[0]=QaHarness.spawn(h.getLevel(),origin,QaHarness.Scene.PIGLIN));
        h.runAtTickTime(280,()->{h.assertTrue(s[0].sawProjectile&&PiglinState.runtime(s[0].mob).shots>=2&&s[0].target.getHealth()<1000,"QA native Brain main/off shots and collision");proof("qa_piglin",s[0].mob,"hp="+s[0].target.getHealth());QaHarness.cleanup(server);});
        h.runAtTickTime(290,()->s[0]=QaHarness.spawn(h.getLevel(),origin,QaHarness.Scene.PIGLIN_DODGE));
        h.runAtTickTime(610,()->{h.assertTrue(PiglinState.runtime(s[0].mob).dodges==1,"QA default-cooldown native Brain dodge");proof("qa_dodge",s[0].mob,"movement="+s[0].maxMove);QaHarness.cleanup(server);});
        h.runAtTickTime(620,()->s[0]=QaHarness.spawn(h.getLevel(),origin,QaHarness.Scene.PIGLIN_ANGER));
        h.runAtTickTime(660,()->{h.assertTrue(s[0].mob.getHealth()<20&&s[0].mob.getTarget()==null&&s[0].target.getHealth()==1000,"QA real same-species injury without retaliation");proof("qa_anger",s[0].mob,"sourceHP=1000");QaHarness.cleanup(server);h.succeed();});}
    @GameTest(environment="buildupmobtweaks:r4e1b",structure=ARENA,maxTicks=135)
    public void reenablingAngerFixRetiresNativeCachedSameSpeciesTarget(GameTestHelper h){SkeletonBehaviorTests.floor(h,true);var m=zombie(h,8,8,false);var source=zombie(h,8,10,true);m.addTag("buildupmobtweaks:disable_zombified_piglin_anger_fix");h.runAtTickTime(5,()->m.hurtServer(h.getLevel(),m.damageSources().mobAttack(source),1));
        h.runAtTickTime(45,()->{h.assertTrue(m.getTarget()==source&&m.getPersistentAngerTarget()!=null,"Native active retaliation first");m.removeTag("buildupmobtweaks:disable_zombified_piglin_anger_fix");});
        h.runAtTickTime(120,()->{h.assertTrue(m.getTarget()==null&&m.getPersistentAngerTarget()==null,"Re-enable retires active target, cached Goal and same-species anger reference");proof("anger_reenable",m,"reference=none");clean(m,source);h.succeed();});}
    @GameTest(environment="buildupmobtweaks:r4e1b",structure=ARENA,maxTicks=220)
    public void goldReplacingOffhandCrossbowTransfersItOnceBeforeBarter(GameTestHelper h){var m=piglin(h,Items.CROSSBOW,true);var bow=m.getOffhandItem();bow.setDamageValue(31);bow.set(DataComponents.CUSTOM_NAME,Component.literal("offhand barter bow"));m.setCanPickUpLoot(true);m.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);
        h.runAtTickTime(10,()->{h.assertTrue(m.getOffhandItem()==bow,"Compatible offhand survives native core cleanup");var gold=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),m.getX(),m.getY(),m.getZ(),new ItemStack(Items.GOLD_INGOT));gold.setNoPickUpDelay();h.getLevel().addFreshEntity(gold);});
        h.runAtTickTime(205,()->{var drops=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,m.getBoundingBox().inflate(16));var all=new ArrayList<ItemStack>();all.add(m.getMainHandItem());all.add(m.getOffhandItem());for(int i=0;i<m.getInventory().getContainerSize();i++)all.add(m.getInventory().getItem(i));for(var e:drops)all.add(e.getItem());
            h.assertTrue(all.stream().filter(s->s.is(Items.CROSSBOW)&&s.getDamageValue()==31&&s.getHoverName().getString().equals("offhand barter bow")).mapToInt(ItemStack::getCount).sum()==1,"Native gold replacement keeps exactly one actual component-bearing bow across hands/inventory/drops");h.assertTrue(m.getOffhandItem().isEmpty()&&drops.stream().anyMatch(e->!e.getItem().is(Items.CROSSBOW)),"Gold barter still completes after weapon transfer");proof("offhand_barter",m,"ownedBow=1 outputs="+drops.size());clean(m);for(var e:drops)e.discard();h.succeed();});}
    @GameTest(environment="buildupmobtweaks:r4e1b_config",structure=ARENA,maxTicks=235)
    public void actualMasterAndTraitConfigGatesKeepNativeBrainShots(GameTestHelper h){var cfg=BuildupMobTweaks.config();boolean master=cfg.general.enabled.get(),traits=cfg.traits.enabled.get();cfg.general.enabled.setAndUpdate(false);
        var m=piglin(h,Items.CROSSBOW,false);m.getAttached(PiglinState.DATA).putString("birth","dodge");m.getAttached(PiglinState.DATA).putLong("dodge_ready",0);var t=target(h,m,14);boolean[] near={false};
        h.onEachTick(()->{if(m.isUsingItem()){near[0]=true;t.snapTo(m.position().add(0,0,1.3),0,0);}});
        h.runAtTickTime(100,()->{try{h.assertTrue(near[0]&&PiglinState.runtime(m).shots>0&&PiglinState.runtime(m).swings==0&&PiglinState.runtime(m).dodges==0,"Actual master off preserves native Brain fire but no additions");cfg.general.enabled.setAndUpdate(true);cfg.traits.enabled.setAndUpdate(false);}catch(RuntimeException|AssertionError e){cfg.general.enabled.setAndUpdate(master);cfg.traits.enabled.setAndUpdate(traits);throw e;}});
        h.runAtTickTime(220,()->{try{h.assertTrue(PiglinState.runtime(m).swings>0&&PiglinState.runtime(m).dodges==0,"Traits off only suppresses dodge; normal compatibility/swing still work");proof("config_gates",m,"master/traits native=true");clean(m,t);h.succeed();}finally{cfg.general.enabled.setAndUpdate(master);cfg.traits.enabled.setAndUpdate(traits);}});}
    @GameTest(environment="buildupmobtweaks:r4e1b",structure=ARENA,maxTicks=370)
    public void nativeOverworldConversionTransfersGearOnceWithoutCrossbowAi(GameTestHelper h){var m=piglin(h,Items.CROSSBOW,true);m.setImmuneToZombification(false);m.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0);var bow=m.getOffhandItem();bow.setDamageValue(19);bow.set(DataComponents.CUSTOM_NAME,Component.literal("conversion bow"));m.getInventory().setItem(0,new ItemStack(Items.GOLD_NUGGET,5));
        h.runAtTickTime(350,()->{var converted=h.getLevel().getEntitiesOfClass(ZombifiedPiglin.class,m.getBoundingBox().inflate(8));h.assertTrue(m.isRemoved()&&converted.size()==1,"Actual native 300 tick overworld conversion");var z=converted.getFirst();h.assertTrue(z.getOffhandItem().is(Items.CROSSBOW)&&z.getOffhandItem().getCount()==1&&z.getOffhandItem().getDamageValue()==19&&z.getOffhandItem().getHoverName().getString().equals("conversion bow"),"Native conversion transfers exact real gear components once");h.assertTrue(!z.hasAttached(PiglinState.DATA),"No Piglin trait or E2 crossbow AI installed on converted Zombified Piglin");var drops=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,m.getBoundingBox().inflate(8));var owned=new ArrayList<ItemStack>();owned.add(z.getMainHandItem());owned.add(z.getOffhandItem());for(var e:drops)owned.add(e.getItem());int nuggets=owned.stream().filter(s->s.is(Items.GOLD_NUGGET)).mapToInt(ItemStack::getCount).sum();proof("conversion_diag",z,"main="+z.getMainHandItem()+" off="+z.getOffhandItem()+" drops="+drops.stream().map(e->e.getItem().toString()).toList()+" sourceInventory="+m.getInventory().getItems());h.assertTrue(m.getInventory().isEmpty()&&nuggets==5&&owned.stream().filter(s->s.is(Items.CROSSBOW)).mapToInt(ItemStack::getCount).sum()==1,"Native conversion empties original inventory and conserves drops plus actual converted hands exactly once");proof("native_conversion",z,"offBow=1 totalNuggets="+nuggets);clean(z);for(var e:drops)e.discard();h.succeed();});}
